}", "middlewares/closing_check.py": """"Before the agent finishes: if its final message says a step was not done, send it back to do that step."""

def check(ctx, event):
    final = str(event.get('final_message', ''))
    if 'Not done:' in final:
        missing = final.split('Not done:', 1)[1].strip()
        return {'action': 'block', 'message': 'Before finishing, do the step your message says is not done: ' + missing}
    return {'action': 'continue'}
