def test_an_unfinished_closing_step_sends_the_agent_back(ctx):
    result = _check()(ctx, {'final_message': 'Done: updated. Not done: the closing step.', 'turn': 2})
    assert result['action'] == 'block' and 'the closing step' in result['message']


